$:set -eu
cd workspaces/codespace-terminal-mcp
npm install --no-audit --no-fund >/dev/null
cat >/tmp/verify-mcp-client.mjs <<'EOF'
import { Client } from '${process.cwd()}/node_modules/@modelcontextprotocol/sdk/client/index.js';
import { StreamableHTTPClientTransport } from '${process.cwd()}/node_modules/@modelcontextprotocol/sdk/client/streamableHttp.js';
const client=new Client({name:'terminal-test',version:'1.0.0'});
await client.connect(new StreamableHTTPClientTransport(new URL('http://127.0.0.1:39772/mcp')));
const tools=await client.listTools();
console.log('TOOLS',JSON.stringify(tools.tools.map(t=>t.name)));
const result=await client.callTool({name:'terminal_execute',arguments:{runOn:'$',whatPrompt:'printf MCP_READY; pwd',forWhom:'GPT6_0000000829-test-Terminals'}});
console.log('CALL',JSON.stringify(result));
await client.close();
EOF
sed -i "s|\${process.cwd()}|$(pwd)|g" /tmp/verify-mcp-client.mjs
PORT=39772 node http-server.mjs >/tmp/mcp-server-test.log 2>&1 &
pid=$!
trap 'kill $pid 2>/dev/null || true' EXIT
sleep 2
node /tmp/verify-mcp-client.mjs
